#' Export Gene Ontology (GO) results to Excel.
#'
#' It exports the results obtained with the function GCP_GO() in one or two .xlsx files in the current working directory.
#'
#' @param GO_list A list obtained with the function GCP_GO().
#' @param file_name_GO The name you want to assign to the generated file, or the full file path.
#' @param export_considered_gene_names logical. If TRUE, an additional file will be exported, with the information related to genes used in the computed GOs.
#' @param file_name_considered_gene_names The name you want to assign to the file related to the considered gene names, or the full file path, if export_considered_gene_names is TRUE.
#'
#' @return It exports one or two file in the current working directory.
#'
#'
#' @examples
#'
#' \dontrun{
#'
#' this_GO_list <- GCP_GO(GCPlist = GCPlist12a2,
#'                        name_column_groups = "Group_multi",
#'                        OrgDb = "mouse")
#'
#' GCP_GO_export(GO_list = this_GO_list,
#'               file_name_GO = "GO_results",
#'               export_considered_gene_names = TRUE,
#'               file_name_considered_gene_names = "GO_considered_gene_names")
#'
#' }
#'
#' @importFrom writexl write_xlsx
#'
#' @export
GCP_GO_export <- function(GO_list,
                          file_name_GO = "GO_results",
                          export_considered_gene_names = FALSE,
                          file_name_considered_gene_names = "GO_considered_gene_names") {

  if (!is.list(GO_list)) {stop("GO_list must be a list generated by GCP_GO()")}
  if (length(GO_list)!=3) {stop("GO_list must be a list generated by GCP_GO()")}
  if (is.null(names(GO_list))) {stop("GO_list must be a list generated by GCP_GO()")}
  if (any(duplicated(names(GO_list)))) {stop("GO_list must be a list generated by GCP_GO()")}
  if (!all(names(GO_list) %in% c("considered_gene_names", "SUMMARY_gene_names", "GO_results"))) {stop("GO_list must be a list generated by GCP_GO()")}

  if (!is.list(GO_list$GO_results)) {stop("GO_list$GO_results must be a list")}
  if (length(GO_list$GO_results) < 1) {stop("GO_list$GO_results must be a non-empty list")}
  if (!all(unname(map_lgl(GO_list$GO_results, is.null)) | unname(map_lgl(GO_list$GO_results, is.data.frame)))) {stop("GO_list$GO_results must be a list of NULL or of data frames")}
  if (is.null(names(GO_list$GO_results))) {stop("GO_list$GO_results must have names")}

  if (length(file_name_GO)!=1) {stop("file_name_GO must be a character of length 1")}
  if (is.na(file_name_GO)) {stop("file_name_GO must not be NA")}
  file_name_GO <- as.character(file_name_GO)
  if (!endsWith(tolower(file_name_GO), ".xlsx")) {
    file_name_GO <- paste0(file_name_GO, ".xlsx")
  }

  if (length(export_considered_gene_names)!=1) {stop("export_considered_gene_names must be TRUE or FALSE")}
  if (is.na(export_considered_gene_names)) {stop("export_considered_gene_names must be TRUE or FALSE")}
  if (!is.logical(export_considered_gene_names)) {stop("export_considered_gene_names must be TRUE or FALSE")}

  if (export_considered_gene_names) {
    if (length(file_name_considered_gene_names)!=1) {stop("file_name_considered_gene_names must be a character of length 1")}
    if (is.na(file_name_considered_gene_names)) {stop("file_name_considered_gene_names must not be NA")}
    file_name_considered_gene_names <- as.character(file_name_considered_gene_names)
    if (!endsWith(tolower(file_name_considered_gene_names), ".xlsx")) {
      file_name_considered_gene_names <- paste0(file_name_considered_gene_names, ".xlsx")
    }
    if (tolower(file_name_GO) == tolower(file_name_considered_gene_names)) {stop("Please name file_name_GO and file_name_considered_gene_names in different ways!")}

    if (!is.list(GO_list$considered_gene_names)) {stop("GO_list$considered_gene_names must be a list")}
    if (!all(unname(map_lgl(GO_list$considered_gene_names, is.list)))) {stop("GO_list$considered_gene_names must be a list of lists")}
    if (!is.data.frame(GO_list$SUMMARY_gene_names)) {stop("GO_list$SUMMARY_gene_names must be a data frame")}

    if (is.null(names(GO_list$considered_gene_names))) {stop("GO_list$considered_gene_names must be named")}
    if (any(names(GO_list$considered_gene_names)=="SUMMARY_gene_names"))  {stop("Please, just do not call 'SUMMARY_gene_names' any of the lists in GO_list$considered_gene_names")}
    if (length(names(GO_list$considered_gene_names)) != length(colnames(GO_list$SUMMARY_gene_names)[-1])) {stop("The list names of GO_list$considered_gene_names must be the same as the column names of GO_list$SUMMARY_gene_names")}
    if (!(all(names(GO_list$considered_gene_names) == colnames(GO_list$SUMMARY_gene_names)[-1]))) {stop("The list names of GO_list$considered_gene_names must be the same as the column names of GO_list$SUMMARY_gene_names")}

    for (lgena in names(GO_list$considered_gene_names)) {
      if (length(names(GO_list$considered_gene_names[[lgena]])) != nrow(GO_list$SUMMARY_gene_names)) {stop("each list in GO_list$considered_gene_names must have the same names as row names of GO_list$SUMMARY_gene_names")}
      if (!(all(names(GO_list$considered_gene_names[[lgena]]) == pull(GO_list$SUMMARY_gene_names, 1)))) {stop("each list in GO_list$considered_gene_names must have the same names as row names of GO_list$SUMMARY_gene_names")}

    }
  }


  for (GOe in names(GO_list$GO_results)) {
    if (is.null(GO_list$GO_results[[GOe]])) {
      GO_list$GO_results[[GOe]] <- tibble(aaaa = character())
      colnames(GO_list$GO_results[[GOe]]) <- "No results"
    } else {
      GO_list$GO_results[[GOe]] <- rownames_to_column(GO_list$GO_results[[GOe]])
      colnames(GO_list$GO_results[[GOe]])[1] <- ""
    }
  }


  writexl::write_xlsx(GO_list$GO_results, file_name_GO)

  cat(paste0("\n\nThe file '", file_name_GO, "' has been created!\n"))


  if (export_considered_gene_names) {

    considered_gene_names_to_export <- vector(mode = "list", length = length(GO_list$considered_gene_names)+1)
    names(considered_gene_names_to_export) <- c("SUMMARY_gene_names", names(GO_list$considered_gene_names))

    for (cgnts in names(considered_gene_names_to_export)) {
      if (cgnts == "SUMMARY_gene_names") {
        considered_gene_names_to_export[[cgnts]] <- GO_list$SUMMARY_gene_names
      } else {

        all_protid <- character()
        creating_tibbles_to_be_merged <- vector(mode = "list", length = length(GO_list$considered_gene_names[[cgnts]]))
        names(creating_tibbles_to_be_merged) <- names(GO_list$considered_gene_names[[cgnts]])
        for (specgenes in names(GO_list$considered_gene_names[[cgnts]])) {
          all_protid <- c(all_protid, names(GO_list$considered_gene_names[[cgnts]][[specgenes]]))
          creating_tibbles_to_be_merged[[specgenes]] <- tibble(protid = names(GO_list$considered_gene_names[[cgnts]][[specgenes]]),
                                                               THE_NEW_COL = unname(GO_list$considered_gene_names[[cgnts]][[specgenes]]))
          colnames(creating_tibbles_to_be_merged[[specgenes]])[2] <- specgenes
        }

        this_tibble_merged <- tibble(protid = unique(all_protid))
        for (specgeness in names(GO_list$considered_gene_names[[cgnts]])) {
          this_tibble_merged <- left_join(this_tibble_merged, creating_tibbles_to_be_merged[[specgeness]], by = "protid")
        }

        considered_gene_names_to_export[[cgnts]] <- this_tibble_merged
      }
    }


    writexl::write_xlsx(considered_gene_names_to_export, file_name_considered_gene_names)

    cat(paste0("\nAnd the file '", file_name_considered_gene_names, "' has been also created!\n"))
  }

  cat("\n")
}

